    def _wrap_startup_handler(
        handler: Callable[[], Any],
        error_handler: Callable[[Exception], None],
    ) -> Callable[[], Any]:
        """
        Wrap a startup event handler so that any exception it raises is handed
        off to ``error_handler`` instead of propagating.

        The handler returned preserves the sync/async nature of the original
        callable: async callables remain awaitable, sync callables remain
        plain callables.
        """
        if is_async_callable(handler):

            async def async_wrapper() -> None:
                try:
                    await handler()  # type: ignore[misc]
                except Exception as exc:
                    error_handler(exc)

            return async_wrapper

        def sync_wrapper() -> None:
            try:
                handler()
            except Exception as exc:
                error_handler(exc)

